// Neural voice-over playback. Lines come from src/data/voice_lines.json and the
// MP3s generated by scripts/gen_voices.py into public/voices/.
import DATA from './data/voice_lines.json';
import { pick } from './utils.js';

export class VoiceBank {
  constructor(audio) {
    this.audio = audio;
    this.mature = false;
    this.cache = new Map();
    this.byEvent = new Map();
    for (const l of DATA.lines) {
      if (!this.byEvent.has(l.event)) this.byEvent.set(l.event, []);
      this.byEvent.get(l.event).push(l);
    }
    this.busyUntil = 0;
    this.current = null;
  }

  lines(ev) {
    const all = this.byEvent.get(ev) || [];
    const mature = all.filter((l) => l.mode === 'mature');
    // In 18+ mode prefer uncensored lines ~60% of the time when available.
    if (this.mature && mature.length && Math.random() < 0.6) return mature;
    return all.filter((l) => l.mode !== 'mature' && (l.mode !== 'clean' || !this.mature));
  }

  has(ev) { return this.lines(ev).length > 0; }

  async buffer(id) {
    if (this.cache.has(id)) return this.cache.get(id);
    const p = (async () => {
      const r = await fetch(`voices/${id}.mp3`);
      if (!r.ok) throw new Error('missing voice ' + id);
      return this.audio.ctx.decodeAudioData(await r.arrayBuffer());
    })();
    this.cache.set(id, p);
    p.catch(() => this.cache.delete(id));
    return p;
  }

  preload() {
    // warm the common short lines so the first crash isn't silent
    for (const ev of ['crash', 'hitPed', 'wanted', 'copShout', 'pain', 'missionDone', 'gunPanic']) for (const l of this.byEvent.get(ev) || []) this.buffer(l.id).catch(() => {});
  }

  // Play a specific line (cutscenes). Resolves with its duration in seconds.
  async playId(id, onSub) {
    const a = this.audio;
    const line = DATA.lines.find((l) => l.id === id);
    if (!line || !a.ctx) return 2;
    if (this.current) { try { this.current.stop(); } catch { /* done */ } }
    onSub?.(line);
    try {
      const buf = await this.buffer(id);
      const s = a.ctx.createBufferSource();
      s.buffer = buf;
      const g = a.ctx.createGain(); g.gain.value = 1.5;
      s.connect(g); g.connect(a.memeBus);
      s.start();
      this.current = s;
      this.busyUntil = a.t + buf.duration;
      a.duck(buf.duration + 0.3);
      return buf.duration;
    } catch {
      a.say({ hi: line.say, en: line.en }, true);
      return Math.max(2, line.en.length / 14);
    }
  }

  stop() { if (this.current) { try { this.current.stop(); } catch { /* done */ } this.current = null; } }

  // Play a random line for the event. Returns the line (for subtitles) or null.
  play(ev, { priority = false, vol = 1, onSub } = {}) {
    const a = this.audio;
    if (!a.ctx || a.muted) return null;
    const list = this.lines(ev);
    if (!list.length) return null;
    if (!priority && a.t < this.busyUntil) return null;
    const line = pick(list);
    if (priority && this.current) { try { this.current.stop(); } catch { /* already stopped */ } }
    this.busyUntil = a.t + 0.3; // reserve while loading
    this.buffer(line.id).then((buf) => {
      const s = a.ctx.createBufferSource();
      s.buffer = buf;
      const g = a.ctx.createGain(); g.gain.value = vol * 1.4;
      s.connect(g); g.connect(a.memeBus);
      s.start();
      this.current = s;
      this.busyUntil = a.t + buf.duration;
      a.duck(buf.duration);
      onSub?.(line);
    }).catch(() => {
      // fall back to browser speech if the mp3 is missing
      a.say({ hi: line.say, en: line.en }, priority);
      onSub?.(line);
    });
    return line;
  }
}
